    51→
    52→  has(productId) {
    53→    // Convert to string for comparison to handle both number and string IDs
    54→    const searchId = String(productId);
    55→    return this.items.some(item => String(item.id) === searchId);
    56→  },
    57→
    58→  toggle(product) {
    59→    if (this.has(product.id)) {
