    68→  add(product) {
    69→    if (!this.has(product.id)) {
    70→      this.items.push(product);
    71→      window.dispatchEvent(new CustomEvent('wishlist:added', { detail: product }));
    72→
    73→      // Sync with server if authenticated
    74→      if (this.isAuthenticated) {
    75→        this.addToServer(product.id);
    76→      }
