    84→    window.dispatchEvent(new CustomEvent('wishlist:removed', { detail: { productId: removeId } }));
    85→
    86→    // Sync with server if authenticated
    87→    if (this.isAuthenticated) {
    88→      this.removeFromServer(productId);
    89→    }
    90→  },
    91→
    92→  clear() {
    93→    this.items = [];
    94→    window.dispatchEvent(new CustomEvent('wishlist:cleared'));
    95→
    96→    // Clear on server if authenticated
    97→    if (this.isAuthenticated) {
    98→      this.clearOnServer();
    99→    }
   100→  },
