   106→  // Server sync methods
   107→  async addToServer(productId) {
   108→    try {
   109→      await fetch('/moderna-api/wishlist/add', {
   110→        method: 'POST',
   111→        headers: { 'Content-Type': 'application/json' },
   112→        credentials: 'include',
   113→        body: JSON.stringify({ product_id: productId })
   114→      });
   115→    } catch (error) {
   116→      console.error('Failed to add to server wishlist:', error);
   117→    }
   118→  },
   119→
   120→  async removeFromServer(productId) {
   121→    try {
   122→      await fetch('/moderna-api/wishlist/remove', {
   123→        method: 'POST',
   124→        headers: { 'Content-Type': 'application/json' },
   125→        credentials: 'include',
   126→        body: JSON.stringify({ product_id: productId })
   127→      });
   128→    } catch (error) {
   129→      console.error('Failed to remove from server wishlist:', error);
   130→    }
   131→  },
   132→
   133→  async clearOnServer() {
   134→    try {
   135→      await fetch('/moderna-api/wishlist/clear', {
   136→        method: 'POST',
   137→        credentials: 'include'
   138→      });
   139→    } catch (error) {
   140→      console.error('Failed to clear server wishlist:', error);
   141→    }
   142→  },
   143→
   144→  // Sync local wishlist with server (merge)
   145→  async syncWithServer() {
   146→    if (this.isSyncing) return;
   147→    this.isSyncing = true;
   148→
   149→    try {
   150→      // Get current local items before sync
   151→      const localItems = [...this.items];
   152→      console.log('[Wishlist] Syncing with server, local items:', localItems);
   153→
   154→      const response = await fetch('/moderna-api/wishlist/sync', {
   155→        method: 'POST',
   156→        headers: { 'Content-Type': 'application/json' },
   157→        credentials: 'include',
   158→        body: JSON.stringify({ items: localItems })
   159→      });
   160→
   161→      console.log('[Wishlist] Sync response status:', response.status);
   162→
   163→      if (response.ok) {
   164→        const data = await response.json();
   165→        console.log('[Wishlist] Sync response data:', data);
   166→
   167→        if (data.success && data.items) {
   168→          console.log('[Wishlist] Server returned', data.items.length, 'items');
   169→
   170→          // Clear current items and add merged ones
