   185→          } catch (e) {
   186→            console.error('[Wishlist] Failed to save to localStorage:', e);
   187→          }
   188→
   189→          console.log('[Wishlist] Updated store items:', this.items.length, 'items');
   190→
   191→          // Dispatch event after a small delay to ensure DOM is updated
   192→          setTimeout(() => {
   193→            window.dispatchEvent(new CustomEvent('wishlist:synced', { detail: { items: [...this.items] } }));
   194→            console.log('[Wishlist] Dispatched wishlist:synced event');
   195→          }, 100);
   196→        }
   197→      } else {
   198→        const errorData = await response.json();
   199→        console.log('[Wishlist] Sync error:', errorData);
   200→      }
   201→    } catch (error) {
   202→      console.error('[Wishlist] Failed to sync with server:', error);
   203→    } finally {
   204→      this.isSyncing = false;
   205→    }
   206→  },
