   200→<script>
   201→function recentlyViewedComponent(excludeProductId, maxItems) {
   202→    return {
   203→        items: [],
   204→        filteredItems: [],
   205→
   206→        init() {
   207→            // Load items from Alpine store
   208→            this.loadItems();
   209→
   210→            // Listen for recentlyViewed updates
   211→            window.addEventListener('recentlyviewed:added', () => this.loadItems());
   212→            window.addEventListener('recentlyviewed:removed', () => this.loadItems());
   213→            window.addEventListener('recentlyviewed:cleared', () => this.loadItems());
   214→        },
   215→
   216→        loadItems() {
   217→            if (window.Alpine && window.Alpine.store('recentlyViewed')) {
   218→                // Get all items from store (sorted by viewedAt, newest first)
   219→                const allItems = window.Alpine.store('recentlyViewed').getAll();
   220→
   221→                // Filter out excluded product if specified
   222→                this.items = allItems.filter(item => {
   223→                    // Convert both to strings for comparison
   224→                    return excludeProductId === null || String(item.id) !== String(excludeProductId);
   225→                });
   226→
   227→                // Limit to maxItems
   228→                this.filteredItems = this.items.slice(0, maxItems);
   229→            } else {
   230→                this.items = [];
   231→                this.filteredItems = [];
   232→            }
   233→        }
   234→    };
   235→}
   236→</script>
